(5247575, 762283, 96751, '<td valign="top">VERY nicely done.  Great detail and tones, wonderful and interesting lighting.</td>', 'VERY nicely done.  Great detail and tones, wonderful and interesting lighting.', '2009-02-09 18:07:27.000000', NULL, 1),
(5247576, 763777, 31637, '<td valign="top">WOW, I almost thought he was fake at first! Too cute.</td>', 'WOW, I almost thought he was fake at first! Too cute.', '2009-02-09 18:07:52.000000', NULL, 1),
