(5258359, 762283, 54446, '<td valign="top">Congratulations, Jennifer, on your top ten finish.  Gorgeous improvement over the Brown "inspiration".  Thanks for following the challenge rules.... in letter, and spirit.</td>', 'Congratulations, Jennifer, on your top ten finish.  Gorgeous improvement over the Brown "inspiration".  Thanks for following the challenge rules.... in letter, and spirit.', '2009-02-16 00:39:20.000000', NULL, 0),
(5258362, 763436, 54446, '<td valign="top">Good one, andgrogeus.  Thanks for listing the Brown inspiration title and the challenge name.  It was easy to find the brown.  This works great.  Beautiful image.... which stands on its own merits.  Congratulations.</td>', 'Good one, andgrogeus.  Thanks for listing the Brown inspiration title and the challenge name.  It was easy to find the brown.  This works great.  Beautiful image.... which stands on its own merits.  Congratulations.', '2009-02-16 00:41:33.000000', NULL, 0),
